def migrar_setores_para_alas(apps, schema_editor):
    db = schema_editor.connection.alias
    Ala = apps.get_model('admin_cadastros', 'Ala')
    Setor = apps.get_model('admin_cadastros', 'Setor')
    Local = apps.get_model('admin_cadastros', 'Local')

    alas = {}
    estabelecimentos = Setor.objects.using(db).values_list(
        'estabelecimento_id', flat=True).distinct()
    for estabelecimento_id in estabelecimentos:
        for internacao, nome in ((True, 'Internação'), (False, 'Externa')):
            ala, _ = Ala.objects.using(db).get_or_create(
                estabelecimento_id=estabelecimento_id,
                nome=nome,
                status='A',
                defaults={'internacao': internacao},
            )
            alas[(estabelecimento_id, internacao)] = ala.pk

    for setor in Setor.objects.using(db).order_by('pk'):
        locais_por_classificacao = {False: [], True: []}
        for local_id, internacao in Local.objects.using(db).filter(
                setor_id=setor.pk).values_list('pk', 'internacao'):
            locais_por_classificacao[bool(internacao)].append(local_id)

        classificacoes = [
            internacao for internacao, ids in locais_por_classificacao.items()
            if ids
        ] or [False]
        # Em setor misto, mantemos os locais externos no setor original e
        # copiamos o setor apenas para os locais de internação.
        original_internacao = classificacoes[0] if len(classificacoes) == 1 \
            else False
        setor.ala_id = alas[(setor.estabelecimento_id, original_internacao)]
        setor.save(using=db, update_fields=['ala'])

        for internacao in classificacoes:
            if internacao == original_internacao:
                continue
            marcador = ' [Ala:Internação]' if internacao else ' [Ala:Externa]'
            base_nome = setor.nome[:100 - len(marcador)]
            nome = f'{base_nome}{marcador}'
            sequencia = 2
            while Setor.objects.using(db).filter(
                    estabelecimento_id=setor.estabelecimento_id,
                    nome=nome, status=setor.status).exists():
                sufixo = f'{marcador} ({sequencia})'
                nome = f'{setor.nome[:100 - len(sufixo)]}{sufixo}'
                sequencia += 1

            novo_setor = Setor.objects.using(db).create(
                estabelecimento_id=setor.estabelecimento_id,
                ala_id=alas[(setor.estabelecimento_id, internacao)],
                nome=nome,
                status=setor.status,
                dt_registro=setor.dt_registro,
                us_registro_id=setor.us_registro_id,
                dt_atualizacao=setor.dt_atualizacao,
                us_atualizacao_id=setor.us_atualizacao_id,
            )
            Local.objects.using(db).filter(
                pk__in=locais_por_classificacao[internacao]
            ).update(setor_id=novo_setor.pk)


def restaurar_classificacao_local(apps, schema_editor):
    db = schema_editor.connection.alias
    Local = apps.get_model('admin_cadastros', 'Local')
    for local in Local.objects.using(db).select_related('setor__ala'):
        if local.setor_id and local.setor.ala_id:
            local.internacao = local.setor.ala.internacao
            local.save(using=db, update_fields=['internacao'])


